func (l *lexer) finalizeHeredoc(val []rune, marker string) ([]rune, error) {
	working := append([]rune(nil), val...)
	contentLines, closingLine := collectHeredocLines(working)

	markerLen := len(marker)
	paddingToStrip := closingLine
	closingLen := len(closingLine)
	if closingLen >= markerLen {
		paddingToStrip = closingLine[:closingLen-markerLen]
	}

	padLen := len(paddingToStrip)
	heredocStartLine := l.line
	nContent := len(contentLines)
	if nContent == 0 {
		return []rune{}, nil
	}

	var out string
	for lineNum, lineText := range contentLines {
		// find an exact match for the padding
		lineLen := len(lineText)
		index := -1

		if padLen == 0 {
			index = 0
		} else if lineLen < padLen {
			index = strings.Index(lineText, paddingToStrip)
		} else {
			samePrefix := true
			for i := 0; i < padLen && samePrefix; i++ {
				samePrefix = lineText[i] == paddingToStrip[i]
			}
			if samePrefix {
				index = 0
			} else {
				index = strings.Index(lineText, paddingToStrip)
			}
		}

